/// Wrapper that carries one native or VM value for generated harness bindings.
pub(crate) enum HarnessValue<Native, Vm> {
    /// Native value variant.
    Native(Native),
    /// VM value variant.
    Vm(Vm),
}

impl<Native: Clone, Vm: Clone> Clone for HarnessValue<Native, Vm> {
    fn clone(&self) -> Self {
        match self {
            HarnessValue::Native(value) => HarnessValue::Native(value.clone()),
            HarnessValue::Vm(value) => HarnessValue::Vm(value.clone()),
        }
    }
}

impl<Native, Vm> HarnessValue<Native, Vm> {
    /// Convert one wrapper into one native value.
    fn into_native(self, label: &str) -> RuntimeResult<Native> {
        match self {
            HarnessValue::Native(value) => Ok(value),
            HarnessValue::Vm(_) => Err(RuntimeError::from(
                HarnessPlatformError::invalid_argument_value(
                    label,
                    "expected native harness value",
                ),
            )
            .boxed()),
        }
    }

    /// Convert one wrapper into one VM value.
    fn into_vm(self, label: &str) -> RuntimeResult<Vm> {
        match self {
            HarnessValue::Vm(value) => Ok(value),
            HarnessValue::Native(_) => Err(RuntimeError::from(
                HarnessPlatformError::invalid_argument_value(label, "expected VM harness value"),
            )
            .boxed()),
        }
    }
}
